import {state} from './state.js';

export const money=minor=>new Intl.NumberFormat(state.locale,{style:'currency',currency:'EUR'}).format(minor/100);
export const number=value=>new Intl.NumberFormat(state.locale).format(value);
export const digits=raw=>String(raw).replace(/[٠-٩۰-۹]/g,ch=>String(ch.charCodeAt(0)-(ch<='٩'?0x660:0x6f0)));

// Validate grouping and precision before converting to integer cents. An explicit
// locale keeps a draft from being reinterpreted when the UI language changes.
export function parseAmount(raw, locale=state.locale) {
  const text=digits(raw).trim();
  const [group,decimal]=locale==='de'?['.',',']:locale==='ar'?['٬','٫']:[',','.'];
  const escaped=char=>char.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  const integer=`(?:\\d+|\\d{1,3}(?:${escaped(group)}\\d{3})+)`;
  if (!new RegExp(`^${integer}(?:${escaped(decimal)}\\d{1,2})?$`).test(text)) return null;
  const [whole,fraction='']=text.split(decimal);
  const minor=Number(whole.split(group).join(''))*100+Number(fraction.padEnd(2,'0'));
  return Number.isSafeInteger(minor) && minor<=99999999 ? minor : null;
}
export function inputAmount(minor,locale=state.locale) {
  return new Intl.NumberFormat(locale,{useGrouping:false,minimumFractionDigits:2,maximumFractionDigits:2}).format(minor/100);
}
export function whole(raw) {
  const text=digits(raw).trim();
  const value=/^\d+$/.test(text)?Number(text):null;
  return Number.isSafeInteger(value) && value>0 ? value : null;
}
export const state = {
  operator: localStorage.getItem('field-desk.operator') || 'robin', locale: 'en',
  route: location.hash.slice(1) || 'orders', search: '', filter: 'ALL', selected: [],
  data: null, modal: null, form: {}, error: null, notice: null,
  notificationsDraft: null, helpCopied: false,
};
export async function api(path, body, operator=state.operator) {
  const response = await fetch(`/api/${path}`, body === undefined ? {} : {
    method: 'POST', headers: {'Content-Type':'application/json','X-Operator':operator},
    body: JSON.stringify(body),
  });
  const data = await response.json();
  if (!response.ok) throw data.error || {code:'REQUEST_FAILED'};
  return data;
}
export async function reload() {
  const operator=state.operator;
  await pendingPreferences(operator);
  const data=await api(`bootstrap?operator=${encodeURIComponent(operator)}`);
  if (operator===state.operator) state.data=data;
}
export const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const value = key => escape(state.form[key] ?? '');

// Serialize preference writes and bind each request to its operator.
const preferenceWrites=new Map();
export function pendingPreferences(operator=state.operator) {
  return preferenceWrites.get(operator) || Promise.resolve();
}
export function savePreferences(preferences, operator=state.operator) {
  const pending=pendingPreferences(operator).catch(()=>{}).then(()=>api('preferences',preferences,operator));
  preferenceWrites.set(operator,pending);
